(async()=>{"use strict";const fail=m=>{const e=document.getElementById("lockError");e.textContent=m;e.style.display="block"};try{const m=await fetch("trip-data.json",{cache:"no-store"}).then(r=>{if(!r.ok)throw 0;return r.json()});window.TRIP_DATA=JSON.parse((await Promise.all(m.chunks.map(f=>fetch(f).then(r=>r.text())))).join(""));const a=["app-01.part", "app-02.part", "app-03.part", "app-04.part", "app-05.part", "app-06.part", "app-07.part"];(0,eval)((await Promise.all(a.map(f=>fetch(f).then(r=>r.text())))).join("")+"\n//# sourceURL=budapest-app.js")}catch(e){console.error(e);fail("No se pudo cargar el itinerario. Recarga con conexión.")}})();
